update uds_ucs_basic2 set k5=SUBSTRING(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(comps,N'क',''),N'ख',''),N'ग',''),N'घ',''),N'च',''),N'छ',''),N'ज',''),N'झ',''),N'त',''),N'थ',''),N'द',''),N'ध',''),N'म',''),N'न',''),N'ङ',''),N'य',''),5,1)where comps not like'%&%' and comps not like'%/%'
update uds_ucs_basic2 set k6=SUBSTRING(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(comps,N'क',''),N'ख',''),N'ग',''),N'घ',''),N'च',''),N'छ',''),N'ज',''),N'झ',''),N'त',''),N'थ',''),N'द',''),N'ध',''),N'म',''),N'न',''),N'ङ',''),N'य',''),6,1)where comps not like'%&%' and comps not like'%/%'
