update uds_ucs_basic2 set k9=SUBSTRING(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(comps,N'क',''),N'ख',''),N'ग',''),N'घ',''),N'च',''),N'छ',''),N'ज',''),N'झ',''),N'त',''),N'थ',''),N'द',''),N'ध',''),N'म',''),N'न',''),N'ङ',''),N'य',''),9,1)where comps not like'%&%' and comps not like'%/%'
--select UNICODE(k2),UNICODE(k3),case when Nchar(UNICODE(k2+k3))=k2+k3 then 1 else 0 end,* from uds_ucs_basic2 where comps like N'%𤰇%' --and unicode(k2)=65535
--select k1,unicode(k1),k2,unicode(k2),k3,unicode(k3),k4,unicode(k4),k5,unicode(k5),k6,unicode(k6),* from uds_ucs_basic2 where k like N'%巕%'
declare @a int=50000,@b int=999999
--select *,k1+k2,k2+k3,k3+k4,k4+k5,k5+k6,k6+k7,k7+k8,k8+k9 from uds_ucs_basic2 where 
--(UNICODE(k1)between @a and @b or
--UNICODE(k2)between @a and @b or
--UNICODE(k3)between @a and @b or
--UNICODE(k4)between @a and @b or
--UNICODE(k5)between @a and @b or
--UNICODE(k6)between @a and @b or
--UNICODE(k7)between @a and @b or
--UNICODE(k8)between @a and @b or
--UNICODE(k9)between @a and @b)
update uds_ucs_basic2 set k1=k1+k2,k2=k3,k3=k4,k4=k5,k5=k6,k6=k7,k7=k8,k8=k9,k9=''
where UNICODE(k1)between @a and @b and len(k1)=1
update uds_ucs_basic2 set		k2=k2+k3,k3=k4,k4=k5,k5=k6,k6=k7,k7=k8,k8=k9,k9=''
where UNICODE(k2)between @a and @b and len(k2)=1
update uds_ucs_basic2 set			  k3=k3+k4,k4=k5,k5=k6,k6=k7,k7=k8,k8=k9,k9=''
where UNICODE(k3)between @a and @b and len(k3)=1
update uds_ucs_basic2 set					k4=k4+k5,k5=k6,k6=k7,k7=k8,k8=k9,k9=''
where UNICODE(k4)between @a and @b and len(k4)=1
update uds_ucs_basic2 set						  k5=k5+k6,k6=k7,k7=k8,k8=k9,k9=''
where UNICODE(k5)between @a and @b and len(k5)=1
update uds_ucs_basic2 set								k6=k6+k7,k7=k8,k8=k9,k9=''
where UNICODE(k6)between @a and @b and len(k6)=1
update uds_ucs_basic2 set									  k7=k7+k8,k8=k9,k9=''
where UNICODE(k7)between @a and @b and len(k7)=1
update uds_ucs_basic2 set											k8=k8+k9,k9=''
where UNICODE(k8)between @a and @b and len(k8)=1
--select * from uds_ucs_basic2 where k9 is null

--alter table uds_ucs_basic2 drop column jlpt,kanken
alter table uds_ucs_basic2 add jlpt int,kanken float
go
update a set a.kanken=k.lvl from uds_ucs_basic2 a join kanken k on k.k collate Japanese_BIN2=a.k collate Japanese_BIN2
update a set a.jlpt=k.jlpt_test from uds_ucs_basic2 a join kanji k on k.kanji collate Japanese_BIN2=a.k collate Japanese_BIN2
go
alter table uds_ucs_basic2 add kanjidic2 nvarchar(20)--collate Japanese_BIN2
go
update a set a.kanjidic2
	=case when k.grade is not null then 'g:'+convert(nvarchar(10),k.grade)else ''end+case when k.freq is not null then 'f:'+convert(nvarchar(10),k.freq)else ''end
from uds_ucs_basic2 a join kanjidic2_literals k on k.literal collate Japanese_BIN2=a.k
go
--drop table if exists #tempkepri
--select distinct k.k,ke_pri1 ke_pri into #tempkepri from kanji_from_jmdict k join jmdict_kanji ke on CHARINDEX(k.k,ke.keb)>0
--where ke.ke_pri1 is not null union
--select distinct k.k,ke_pri2 from kanji_from_jmdict k join jmdict_kanji ke on CHARINDEX(k.k,ke.keb)>0
--where ke.ke_pri2 is not null union
--select distinct k.k,ke_pri3 from kanji_from_jmdict k join jmdict_kanji ke on CHARINDEX(k.k,ke.keb)>0
--where ke.ke_pri3 is not null union
--select distinct k.k,ke_pri4 from kanji_from_jmdict k join jmdict_kanji ke on CHARINDEX(k.k,ke.keb)>0
--where ke.ke_pri4 is not null
--update k set k.ke_pris=ke_pri
--from (select k,string_agg(convert(nvarchar(max),ke_pri),',')within group(order by len(ke_pri)desc,ke_pri)ke_pri from #tempkepri t group by t.k)t
--join kanji_from_jmdict k on k.k=t.k
alter table uds_ucs_basic2 add jmdict nvarchar(300)--collate Japanese_BIN2
go
update a set a.jmdict=replace(isnull(k.ke_pris,''),',','|')collate Japanese_BIN2 from uds_ucs_basic2 a join kanji_from_jmdict k on k.k collate Japanese_BIN2=a.k collate Japanese_BIN2
--select * from kanjidic2_literals k full join uds_ucs_basic2 u on u.k=k.literal collate Japanese_BIN2 where u.k is null or k.literal is null order by k.literal,u.k
--select * from kanji_from_jmdict k full join uds_ucs_basic2 u on u.k=k.k collate Japanese_BIN2 where u.k is null or k.k is null order by k.k,u.k
drop table if exists #temp
;with components as(
select distinct k1 comp from uds_ucs_basic2 where k1 not like N'' union
select distinct k2 from uds_ucs_basic2 where k2 not like N'' union
select distinct k3 from uds_ucs_basic2 where k3 not like N'' union
select distinct k4 from uds_ucs_basic2 where k4 not like N'' union
select distinct k5 from uds_ucs_basic2 where k5 not like N'' union
select distinct k6 from uds_ucs_basic2 where k6 not like N'' union
select distinct k7 from uds_ucs_basic2 where k7 not like N'' union
select distinct k8 from uds_ucs_basic2 where k8 not like N'' union
select distinct k9 from uds_ucs_basic2 where k9 not like N'' union
select distinct k1+k2 from uds_ucs_basic2 where k1=N''and k2=N''union all
select distinct k2+k3 from uds_ucs_basic2 where k2=N''and k3=N''union all
select distinct k3+k4 from uds_ucs_basic2 where k3=N''and k4=N''union all
select distinct k4+k5 from uds_ucs_basic2 where k4=N''and k5=N''union all
select distinct k5+k6 from uds_ucs_basic2 where k5=N''and k6=N''union all
select distinct k6+k7 from uds_ucs_basic2 where k6=N''and k7=N''union all
select distinct k7+k8 from uds_ucs_basic2 where k7=N''and k8=N''union all
select distinct k8+k9 from uds_ucs_basic2 where k8=N''and k9=N'')
select distinct k,comp,jlpt,kanken,kanjidic2,jmdict into #temp from uds_ucs_basic2 join components on comps like'%'+comp+'%'where comp!=N'' --order by uni

drop table if exists #temp2
select comp
,STRING_AGG(k,',')within group(order by kanken desc,jlpt desc,k)k
,STRING_AGG(case when kanken is not null then k end,',')within group(order by kanken desc,jlpt desc,k)k2
,STRING_AGG(jlpt,',')within group(order by kanken desc,jlpt desc,k)jlpt
,STRING_AGG(kanken,',')within group(order by kanken desc,jlpt desc,k)kanken
,STRING_AGG(kanjidic2,',')within group(order by kanken desc,jlpt desc,k)kanjidic2
,STRING_AGG(convert(varchar(max),jmdict),',')within group(order by kanken desc,jlpt desc,k)jmdict
,count(distinct k)kcount
,count(jlpt)jlptcount,count(kanken)kankencount
,count(jlpt)kanjidic2count,count(kanken)jmdictcount
,count(nullif(jlpt,''))kanjidic2goodcount,count(nullif(kanken,''))jmdictgoodcount
into #temp2 from #temp group by comp

update t set t.jlpt=a.jlpt from #temp2 t
join (select comp,k,STRING_AGG(value,',')within group(order by value desc)jlpt from #temp2 t2 cross apply (select distinct value from string_split(t2.jlpt,','))a group by comp,k)a on a.comp=t.comp and a.k=t.k
update t set t.kanken=a.kanken from #temp2 t
join (select comp,k,STRING_AGG(value,',')within group(order by value desc)kanken from #temp2 t2 cross apply (select distinct value from string_split(t2.kanken,','))a group by comp,k)a on a.comp=t.comp and a.k=t.k
update t set t.kanjidic2=a.kanjidic2 from #temp2 t
join (select comp,k,STRING_AGG(value,',')within group(order by value)kanjidic2 from #temp2 t2 cross apply (select distinct value from string_split(replace(t2.kanjidic2,'|',''),',')where value!='')a group by comp,k)a on a.comp=t.comp and a.k=t.k
update t set t.jmdict=a.jmdict from #temp2 t
join (select comp,k,STRING_AGG(value,',')within group(order by len(value) desc,value)jmdict from #temp2 t2 cross apply (select distinct value from string_split(replace(t2.jmdict,'|',''),',')where value!='')a group by comp,k)a on a.comp=t.comp and a.k=t.k

drop table if exists chise_components
select (isnull(convert(numeric(5,3),kankencount*1.0/kcount),0) /*scorekanken*/
+isnull(convert(numeric(5,3),jmdictgoodcount*1.0/kcount),0) /*scorejmdict*/
+isnull(convert(numeric(5,3),kanjidic2goodcount*0.5/kcount),0) /*scorekanjidic2*/)/3
--+isnull(left(jlpt,1)*0.5,0)
+isnull(convert(int,replace(left(replace(kanken,'10','x'),1),'x','10'))*0.5,0)
score,*
into chise_components
from #temp2
--update chise_components set kanjidic2=replace(kanjidic2,',,',',')
--update chise_components set kanjidic2='' where kanjidic2=','

select score/5.433333 score,comp,k,k2,jlpt,kanken,kcount,kankencount,jlptcount,jmdictgoodcount,kanjidic2goodcount from chise_components
--where kankencount>1 and not(kcount=2 and CHARINDEX(comp,k)>0)
order by case when kankencount>1 and len(replace(replace(replace(k,comp+',',''),comp,''),',',''))>2 then 1 else 0 end desc,score desc,len(k)desc,replace(kanken,'10','x') desc,jlptcount desc,k

drop table if exists #temp3
select isnull(kunn.literal,onn.literal)k,kunn.kunyomi,onn.onyomi_hiragana into #temp3 from kanjidic2_literals_onyomi onn
full join kanjidic2_literals_kunyomi kunn on onn.literal=kunn.literal
where kunn.yomirank=1 and onn.yomirank=1

drop table if exists #temp4
select distinct t.k kanji,kunyomi,onyomi_hiragana,nullif(kunyomi,kunyomi)name1,nullif(kunyomi,kunyomi)name2,nullif(kunyomi,kunyomi)name3,c.*
into #temp4 from #temp3 t join chise_components c
on charindex(t.k collate Japanese_BIN2,c.k2)>0
order by c.comp
drop table if exists #temp4_2
select distinct t.k kanji,kunyomi,onyomi_hiragana,nullif(kunyomi,kunyomi)name1,nullif(kunyomi,kunyomi)name2,nullif(kunyomi,kunyomi)name3,c.*
into #temp4_2 from #temp3 t join chise_components c
on charindex(t.k collate Japanese_BIN2,replace(c.k,c.k2,''))>0
order by c.comp

update t set t.name1='-' from #temp4 t where comp!=k and name1 is null and len(k)=1
update t set t.name1='-' from #temp4 t where comp!=k2 and name1 is null and len(k2)=1
update t set t.name1=t2.onyomi_hiragana+N'の'+replace(replace(t2.kunyomi,N'.',''),N'-','')
from #temp4 t join #temp4 t2 on t2.kanji collate Japanese_BIN2=t.comp
where t.name1 is null
update t set t.name1=t2.onyomi_hiragana+N'の'+replace(replace(t2.kunyomi,N'.',''),N'-','')
from #temp4 t join #temp4_2 t2 on t2.kanji collate Japanese_BIN2=t.comp
where t.name1 is null and t2.onyomi_hiragana+N'の'+replace(replace(t2.kunyomi,N'.',''),N'-','') not in (select name1 from #temp4)

drop table if exists #temp5
select score,comp,onyomi_hiragana,kunyomi,STRING_AGG(kanji,',')kanji,count(distinct kanji)tot
into #temp5 from #temp4 where name1 is null --order by comp,onyomi_hiragana
group by score,comp,onyomi_hiragana,kunyomi

drop table if exists #temp6
select score,comp,onyomi_hiragana
,string_agg(replace(replace(kunyomi,N'.',''),N'-','')+N'の'+onyomi_hiragana,',')namecandidate,sum(tot)tot
into #temp6 from #temp5 group by score,comp,onyomi_hiragana order by comp
drop table if exists #temp7
select score,comp,onyomi_hiragana,tot,a.namecandidate into #temp7 from #temp6
cross apply(select value namecandidate from string_split(namecandidate,','))a
delete from #temp7 where namecandidate in (select name1 from #temp4)
;with cte as(select row_number()over(partition by comp order by tot desc)rn,score,comp,onyomi_hiragana,tot,string_agg(namecandidate,',')namecandidate from #temp7 group by score,comp,onyomi_hiragana,tot)
update t set
t.name1=case when namecandidate like'%,%'then left(namecandidate,charindex(',',namecandidate)-1)else namecandidate end --name1
,t.name2=case when namecandidate like'%,%'then right(namecandidate,len(namecandidate)-charindex(',',namecandidate))end --name2
from cte join #temp4 t on t.comp=cte.comp
where rn=1 and t.name1 is null

select distinct name1,name2,comp from #temp4 where name1 is not null
select distinct name1,comp from #temp4 where name1 in (select name1 from #temp4 group by name1 having count(distinct comp)>1)
and name1!='-'
order by name1
--where name1 like N'%しゅうのあつまる%'order by score desc,name1,comp
;with cte as(select distinct convert(numeric(5,4),c.score/5.433333) score,t.name1,isnull(t.name2,'')name2,c.comp
,c.k2 kankenkanji,replace(c.k,c.k2+',','')non_kankenkanji
,c.jlpt,c.kanken,c.kcount,c.kankencount,c.jlptcount,c.jmdictgoodcount,c.kanjidic2goodcount
from chise_components c join #temp4 t on t.comp=c.comp
--where kankencount>1 and not(kcount=2 and CHARINDEX(comp,k)>0)
)select * from cte c
order by case when c.kankencount>1 and len(replace(replace(replace(c.kankenkanji,c.comp+',',''),c.comp,''),',',''))>2 then 1 else 0 end desc,score desc,len(c.kankenkanji)desc,replace(c.kanken,'10','x') desc,c.jlptcount desc,c.kankenkanji



select kcount,kankencount,jlptcount,* from chise_components order by (kankencount*0.75)+(jmdictcount+kanjidic2count+jlptcount)*0.33*0.25 desc,1 desc,score desc
select * from chise_components-- where k4 between N'𱬹'and N'者'
order by case when comp=k then 1 else 0 end asc,kcount desc,kankencount desc,jlptcount desc,comp,k--(kankencount*0.75)+(jmdictcount+kanjidic2count+jlptcount)*0.33*0.25 desc,1 desc,score desc